"""Mobile (phone) web UI for a subgraph pipeline.

The phone page shows only the promoted inputs of the subgraph instances in the
current workflow plus the results, instead of the whole node graph.

Why the frontend prepares the template
-------------------------------------
ComfyUI's ``POST /prompt`` needs the API form, which the desktop frontend
builds with ``app.graphToPrompt()``. Reproducing that on the server is not
reliable: custom nodes serialize widgets with decoration objects, some nodes
are virtual, and bypass/Reroute splicing is node-definition dependent. On the
workflows this was written against, a purely structural expander still missed
4-47 values per workflow.

So the browser — which is already running the official expander — posts the
expanded prompt once, and the phone page only overrides parameter values. The
template is stored next to the workflow, keyed by workflow path, and refreshed
every time the user presses the "手机界面" button.

Parameter binding
-----------------
Along with the prompt the browser sends the *targets* of each promoted input:
``(exec_id, input_name)`` pairs resolved through the subgraph instance. A new
value is written to those slots of the stored prompt, so the phone never has
to understand subgraphs at all.

Endpoints
---------
``POST /qq_mobile/template``   store the expanded prompt + parameter schema
``GET  /qq_mobile/template``   read the stored schema (no prompt) for the form
``POST /qq_mobile/prompt``     override values and queue the prompt
``GET  /qq_mobile/jobs``       poll job status and produced media
``GET  /qq_mobile/media``      serve a produced file (view passthrough)
``POST /qq_mobile/interrupt``  cancel the running job
"""

from __future__ import annotations

import asyncio
import copy
import json
import os
import time
import uuid
from typing import Any
from urllib.parse import urlencode

try:  # ComfyUI runtime
    import aiohttp
    from aiohttp import web
    from server import PromptServer
    import folder_paths
except Exception:  # pragma: no cover - tests run without the server
    aiohttp = None  # type: ignore[assignment]
    web = None  # type: ignore[assignment]
    PromptServer = None  # type: ignore[assignment]
    folder_paths = None  # type: ignore[assignment]

try:  # package import (normal ComfyUI load)
    from .mobile_graph import expand_workflow
except ImportError:  # pragma: no cover - loaded as a standalone module in tests
    from mobile_graph import expand_workflow  # type: ignore[no-redef]

#: How long a prepared template stays usable for polling without a re-send.
TEMPLATE_MAX_AGE_SECONDS = 7 * 24 * 3600

#: Parameter types the phone page can edit as plain values.
EDITABLE_TYPES = {"INT", "FLOAT", "STRING", "BOOLEAN", "COMBO", "combo", "INT:", "FLOAT:"}


class MobileState:
    """In-memory registry of prepared templates, keyed by workflow path."""

    def __init__(self) -> None:
        self.templates: dict[str, dict[str, Any]] = {}
        self.lock = asyncio.Lock()

    def put(self, workflow_key: str, payload: dict[str, Any]) -> dict[str, Any]:
        record = {
            "workflow": workflow_key,
            "title": payload.get("title") or workflow_key,
            "prompt": payload.get("prompt") or {},
            "parameters": payload.get("parameters") or [],
            "outputs": payload.get("outputs") or [],
            # The UI graph, sent back on submission as extra_pnginfo.workflow.
            # Without it ShowText and other nodes that look the workflow up by
            # node id fail, and saved PNGs lose their embedded workflow.
            "graph": payload.get("graph") or {},
            "updated": time.time(),
        }
        self.templates[workflow_key] = record
        return record

    def get(self, workflow_key: str | None) -> dict[str, Any] | None:
        if workflow_key:
            record = self.templates.get(workflow_key)
            if record and time.time() - record["updated"] <= TEMPLATE_MAX_AGE_SECONDS:
                return record
            return None
        if not self.templates:
            return None
        newest = max(self.templates.values(), key=lambda item: item["updated"])
        if time.time() - newest["updated"] > TEMPLATE_MAX_AGE_SECONDS:
            return None
        return newest

    def prune(self) -> None:
        cutoff = time.time() - TEMPLATE_MAX_AGE_SECONDS
        stale = [key for key, value in self.templates.items() if value["updated"] < cutoff]
        for key in stale:
            self.templates.pop(key, None)


STATE = MobileState()


def _normalise_parameters(raw: Any) -> list[dict[str, Any]]:
    """Keep the parameter schema the phone form consumes."""
    parameters: list[dict[str, Any]] = []
    for entry in raw or []:
        if not isinstance(entry, dict):
            continue
        targets = [
            [str(target[0]), str(target[1])]
            for target in entry.get("targets") or []
            if isinstance(target, (list, tuple)) and len(target) == 2
        ]
        parameters.append(
            {
                "key": str(entry.get("key") or entry.get("name") or ""),
                "name": str(entry.get("name") or ""),
                "label": str(entry.get("label") or entry.get("name") or ""),
                "type": str(entry.get("type") or "STRING"),
                "value": entry.get("value"),
                "targets": targets,
                "options": entry.get("options") or None,
                "min": entry.get("min"),
                "max": entry.get("max"),
                "step": entry.get("step"),
                "multiline": bool(entry.get("multiline")),
                "group": entry.get("group"),
                "hidden": bool(entry.get("hidden")),
            }
        )
    return parameters


def apply_parameter_values(
    prompt: dict[str, Any], parameters: list[dict[str, Any]], values: dict[str, Any]
) -> tuple[dict[str, Any], list[str]]:
    """Write submitted *values* into a copy of *prompt*.

    Returns ``(prompt, warnings)``. Unknown keys and parameters without targets
    are reported as warnings instead of raised, so a single stale field cannot
    break the whole submission.
    """
    updated = copy.deepcopy(prompt)
    warnings: list[str] = []
    by_key = {parameter["key"]: parameter for parameter in parameters}

    for key, value in (values or {}).items():
        parameter = by_key.get(key)
        if parameter is None:
            warnings.append(f"未知参数: {key}")
            continue
        targets = parameter.get("targets") or []
        if not targets:
            warnings.append(f"参数 {parameter.get('label') or key} 没有可写入的目标")
            continue
        for exec_id, input_name in targets:
            node = updated.get(exec_id)
            if node is None:
                warnings.append(f"节点 {exec_id} 不在模板中，已跳过 {key}")
                continue
            node.setdefault("inputs", {})[input_name] = value
    return updated, warnings


def collect_outputs(prompt: dict[str, Any]) -> list[dict[str, str]]:
    """Pick output-node media from a prompt without querying the server."""
    return []


#: Media collections ComfyUI output nodes report in history.
OUTPUT_KINDS = ("images", "videos", "gifs", "audio")


def extract_media(history_entry: dict[str, Any]) -> list[dict[str, Any]]:
    """Flatten one ``/history`` entry into a list of displayable media."""
    media: list[dict[str, Any]] = []
    for node_id, payload in (history_entry.get("outputs") or {}).items():
        if not isinstance(payload, dict):
            continue
        for kind in OUTPUT_KINDS:
            for item in payload.get(kind) or []:
                if not isinstance(item, dict) or not item.get("filename"):
                    continue
                media.append(
                    {
                        "node": str(node_id),
                        "kind": kind,
                        "filename": item.get("filename"),
                        "subfolder": item.get("subfolder") or "",
                        "type": item.get("type") or "output",
                        "format": item.get("format"),
                        "metadata": item.get("metadata") or {},
                    }
                )
        for text in payload.get("text") or []:
            if isinstance(text, str) and text.strip():
                media.append({"node": str(node_id), "kind": "text", "text": text})
    return media


def media_url(item: dict[str, Any]) -> str:
    """Build the ``/view`` query for one media entry."""
    query = {
        "filename": item.get("filename", ""),
        "subfolder": item.get("subfolder", ""),
        "type": item.get("type", "output"),
    }
    if item.get("format"):
        query["format"] = item["format"]
    return "/view?" + urlencode(query)


async def _fetch_json(url: str) -> Any:
    async with aiohttp.ClientSession() as session:
        async with session.get(url) as response:
            if response.status >= 400:
                return None
            return await response.json(content_type=None)


def _web_dir() -> str:
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "web")


def _local_base(request: Any) -> str:
    """Base URL for the plugin's own requests *to this same server*.

    ComfyUI sits behind a reverse proxy in the common deployment (Caddy with
    basic auth, nginx, a tunnel). ``request.url`` there is the public address,
    so a self-request built from it goes out to the internet, comes back
    through the proxy, and — because server-to-server calls carry no
    credentials — is challenged with 401. That is the "asked to log in twice"
    symptom: the browser authenticated, then the plugin called itself
    anonymously.

    Calling the loopback address keeps these internal requests off the proxy.
    When the server was started with ``--listen`` on a specific interface only,
    loopback may not be bound, so the bind address is used as a fallback.
    """
    instance = PromptServer.instance
    port = getattr(instance, "port", None) or 8188
    address = str(getattr(instance, "address", "") or "").strip()
    # 0.0.0.0 / :: mean "all interfaces", where loopback works.
    if address in ("", "0.0.0.0", "::", "[::]"):
        return f"http://127.0.0.1:{port}"
    if address in ("localhost", "::1"):
        return f"http://127.0.0.1:{port}"
    return f"http://{address}:{port}"


def _register_routes() -> None:
    try:
        from aiohttp import web  # noqa: F401
        from server import PromptServer  # noqa: F401
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    if server is None or getattr(server, "_qq_mobile_routes", False):
        return

    mobile_page = os.path.join(_web_dir(), "mobile.html")

    @server.routes.get("/qq_mobile/")
    async def qq_mobile_page(request):
        if not os.path.exists(mobile_page):
            return web.json_response({"error": "mobile.html 缺失"}, status=404)
        return web.FileResponse(mobile_page, headers={"Cache-Control": "no-cache"})

    @server.routes.get("/qq_mobile/state")
    async def qq_mobile_state(request):
        STATE.prune()
        records = [
            {
                "workflow": record["workflow"],
                "title": record["title"],
                "parameters": len(record["parameters"]),
                "graph_nodes": len((record.get("graph") or {}).get("nodes") or []),
                "updated": record["updated"],
            }
            for record in STATE.templates.values()
        ]
        return web.json_response({"templates": records})

    @server.routes.post("/qq_mobile/template")
    async def qq_mobile_template(request):
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        workflow_key = str(payload.get("workflow") or "").strip()
        if not workflow_key:
            return web.json_response({"error": "workflow is required"}, status=400)
        prompt = payload.get("prompt")
        if not isinstance(prompt, dict) or not prompt:
            return web.json_response({"error": "prompt is required"}, status=400)

        parameters = _normalise_parameters(payload.get("parameters"))
        graph = payload.get("graph")
        record = STATE.put(
            workflow_key,
            {
                "title": payload.get("title"),
                "prompt": prompt,
                "parameters": parameters,
                "outputs": payload.get("outputs") or [],
                "graph": graph if isinstance(graph, dict) else {},
            },
        )
        return web.json_response(
            {
                "ok": True,
                "workflow": record["workflow"],
                "parameters": len(record["parameters"]),
                "nodes": len(record["prompt"]),
                "graph_nodes": len((record.get("graph") or {}).get("nodes") or []),
            }
        )

    @server.routes.get("/qq_mobile/template")
    async def qq_mobile_get_template(request):
        STATE.prune()
        record = STATE.get(request.query.get("workflow"))
        if record is None:
            return web.json_response({"error": "no template"}, status=404)
        return web.json_response(
            {
                "workflow": record["workflow"],
                "title": record["title"],
                "parameters": record["parameters"],
                "outputs": record["outputs"],
                "updated": record["updated"],
            }
        )

    @server.routes.post("/qq_mobile/prompt")
    async def qq_mobile_prompt(request):
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)

        record = STATE.get(payload.get("workflow"))
        if record is None:
            return web.json_response(
                {"error": "模板不存在，请在 ComfyUI 里重新点击手机界面按钮"}, status=404
            )

        prompt, warnings = apply_parameter_values(
            record["prompt"], record["parameters"], payload.get("values") or {}
        )
        client_id = str(payload.get("client_id") or uuid.uuid4())
        extra_data = build_extra_data(client_id, record.get("graph"))

        # Reuse the official submission path so validation, node replacements,
        # job bookkeeping and WebSocket events all behave exactly as usual.
        # Addressed at the loopback interface so a reverse proxy in front of
        # ComfyUI (and its auth) is not part of our own request path.
        url = f"{_local_base(request)}/prompt"
        headers = {"Content-Type": "application/json"}
        body: dict[str, Any] = {
            "prompt": prompt,
            "client_id": client_id,
            "extra_data": extra_data,
        }
        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    url,
                    data=json.dumps(body),
                    headers=headers,
                ) as response:
                    result = await response.json(content_type=None)
                    status = response.status
        except Exception as exc:  # pragma: no cover - defensive
            return web.json_response({"error": f"提交失败: {exc}"}, status=502)

        if status >= 400:
            return web.json_response(
                {
                    "error": (result or {}).get("error") or "提交被拒绝",
                    "node_errors": (result or {}).get("node_errors") or {},
                },
                status=status,
            )
        prompt_id = (result or {}).get("prompt_id", "")
        if prompt_id:
            SUBMITTED_AT[str(prompt_id)] = time.time()
            # Keep the map from growing during a long session.
            if len(SUBMITTED_AT) > 512:
                cutoff = time.time() - 3600
                for key in [k for k, v in SUBMITTED_AT.items() if v < cutoff]:
                    SUBMITTED_AT.pop(key, None)
        return web.json_response(
            {
                "ok": True,
                "prompt_id": prompt_id,
                "number": (body or {}).get("number"),
                "warnings": warnings,
            }
        )

    @server.routes.post("/qq_mobile/interrupt")
    async def qq_mobile_interrupt(request):
        url = f"{_local_base(request)}/interrupt"
        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(url) as response:
                    return web.json_response({"ok": response.status < 400})
        except Exception as exc:  # pragma: no cover - defensive
            return web.json_response({"error": str(exc)}, status=500)

    @server.routes.get("/qq_mobile/jobs")
    async def qq_mobile_jobs(request):
        """Report the state of one prompt plus whatever media it produced.

        ``/api/jobs/{id}`` is the only endpoint that answers "what is this
        prompt doing" on its own: it checks history, then the running queue,
        then the pending queue, and reports ``in_progress`` / ``pending`` /
        ``completed`` / ``failed`` / ``cancelled``.

        Note that ``GET /prompt`` must NOT be used for this. In this ComfyUI
        version it returns only ``{"exec_info": {"queue_remaining": N}}`` — no
        ``queue_running`` / ``queue_pending`` arrays — so a prompt that is
        actively executing looks absent there and would be reported as lost
        mid-run.
        """
        prompt_id = str(request.query.get("prompt_id") or "").strip()
        base = _local_base(request)
        elapsed = _elapsed_since_submit(request, prompt_id)

        if not prompt_id:
            return web.json_response({"status": "idle", "media": []})

        job = await _fetch_json(f"{base}/api/jobs/{prompt_id}")
        if isinstance(job, dict) and job.get("status"):
            status = str(job["status"])
            payload: dict[str, Any] = {
                "prompt_id": prompt_id,
                "status": status,
                "media": [],
            }
            if status == "pending":
                payload["position"] = await _queue_position(base, prompt_id)
            if status in ("completed", "failed", "cancelled"):
                payload["completed"] = status == "completed"
                payload["media"] = extract_media(job)
                payload["execution_error"] = _execution_error(job)
            return web.json_response(payload)

        # Not known to the job API. That is either the brief moment between a
        # prompt leaving the queue and its history entry landing, or a prompt
        # the server genuinely never ran.
        if elapsed is not None and elapsed < SETTLE_SECONDS:
            return web.json_response(
                {"prompt_id": prompt_id, "status": "settling", "media": []}
            )
        return web.json_response(
            {"prompt_id": prompt_id, "status": "lost", "media": []}
        )

    server._qq_mobile_routes = True


async def _queue_position(base: str, prompt_id: str) -> int | None:
    """Zero-based position of a pending prompt, from the queue listing."""
    queue = await _fetch_json(f"{base}/queue")
    if not isinstance(queue, dict):
        return None
    for position, entry in enumerate(queue.get("queue_pending") or []):
        if _queue_entry_matches(entry, prompt_id):
            return position
    return None


def _execution_error(job: dict[str, Any]) -> str | None:
    """Best-effort message for a job that ended without output."""
    error = job.get("execution_error")
    if isinstance(error, dict):
        return str(error.get("exception_message") or error.get("message") or "")
    if isinstance(error, str) and error:
        return error
    return None


#: How long after submission a prompt may be absent from both the queue and
#: the history before it is treated as lost. ComfyUI writes history slightly
#: after the queue entry disappears, so polling too eagerly would otherwise
#: report a healthy job as cancelled.
SETTLE_SECONDS = 20


def build_extra_data(
    client_id: str, graph: dict[str, Any] | None
) -> dict[str, Any]:
    """Assemble ``extra_data`` the way the official frontend does.

    ``extra_pnginfo.workflow`` is not decoration: nodes with an
    ``EXTRA_PNGINFO`` hidden input read the UI graph to find themselves by node
    id (``ShowText`` rewrites its own ``widgets_values``), and ``SaveImage``
    embeds it so a saved file can be dropped back into ComfyUI. Submitting
    without it makes those nodes log "extra_pnginfo[0] is not a dict or missing
    'workflow' key" and silently strips the workflow from outputs.
    """
    extra: dict[str, Any] = {"client_id": client_id}
    if isinstance(graph, dict) and graph.get("nodes") is not None:
        extra["extra_pnginfo"] = {"workflow": graph}
        # A prompt carrying a graph is tagged with its workflow id so /api/jobs
        # and the history can group runs, matching frontend behaviour.
        workflow_id = graph.get("id")
        if isinstance(workflow_id, str) and workflow_id:
            extra["workflow_metadata"] = {"workflow_id": workflow_id}
    return extra

#: When each prompt was submitted by this page, for the settling window.
SUBMITTED_AT: dict[str, float] = {}


def _elapsed_since_submit(request: web.Request, prompt_id: str) -> float | None:
    """Seconds since this server submitted *prompt_id*, if it did."""
    if not prompt_id:
        return None
    stamp = SUBMITTED_AT.get(prompt_id)
    if stamp is None:
        return None
    return time.time() - stamp


def _queue_entry_matches(entry: Any, prompt_id: str) -> bool:
    """Check whether one ``/prompt`` queue entry belongs to *prompt_id*."""
    if not prompt_id:
        return False
    if isinstance(entry, (list, tuple)):
        return any(str(part) == prompt_id for part in entry[:4])
    if isinstance(entry, dict):
        return str(entry.get("prompt_id")) == prompt_id
    return False


_register_routes()


__all__ = [
    "STATE",
    "MobileState",
    "apply_parameter_values",
    "expand_workflow",
]
